    r"""((D)=>{const lock=(f,g,d)=>{f.toggleAttribute('data-pending',d);d?f.setAttribute('aria-busy',true):f.removeAttribute('aria-busy');for(const b of g)b.disabled=d;};const c=(m,k)=>{if(m&&D.thorToast)D.thorToast(m,k==='success'||k==='error'?k:'info',null);};D.addEventListener('change',(e)=>{const i=e.target,f=i.form,a=i.getAttribute?.('data-t-submit-on-files');if(a==null||i.type!=='file'||!i.files?.length||!f||f.hasAttribute('data-pending'))return;const d=a&&[...f.elements].find((b)=>/^(submit|image)$/.test(b.type)&&(b.name===a||b.getAttribute('formaction')?.endsWith('/'+a)));f.requestSubmit(d||undefined);});D.addEventListener('submit',(e)=>{const f=e.target,s=e.submitter,t=s?.formTarget||f.target;if(e.defaultPrevented||!f.hasAttribute?.('data-t-stay')||!window.fetch||!window.FormData||(t&&t!=='_self'))return;const g=new URL(s?.hasAttribute('formaction')?s.formAction:f.action,location.href);if((s?.formMethod||f.method)!=='post'||g.origin!==location.origin)return;e.preventDefault();if(f.hasAttribute('data-pending'))return;let body;try{body=new FormData(f,s);}catch{body=new FormData(f);if(s?.name)body.append(s.name,s.value);}
const j=[...f.elements].filter((b)=>/^(submit|image)$/.test(b.type)&&!b.disabled);lock(f,j,true);const d=(l)=>{lock(f,j,false);f.dispatchEvent(new CustomEvent('thor:stay',{bubbles:true,detail:l}));};fetch(g,{method:'POST',body:/multipart/i.test(s?.formEnctype||f.enctype)?body:new URLSearchParams(body),headers:{'x-thor-stay':'1'},credentials:'same-origin',}).then((r)=>{const h=(n)=>r.headers.get(n);if(!h('x-thor-stay')){if(r.redirected)return location.assign(r.url);return d({ok:false,status:r.status});}
const o=h('x-thor-location');if(o){const u=new URL(o,location.href);if(/^https?:/.test(u.protocol))return location.assign(u);return d({ok:false,status:r.status});}
