const l=h('x-thor-flash-kind')||(r.ok?'':'error');c(message,l);if(r.ok)for(const i of f.elements)if(i.type==='file')i.value='';d({ok:r.ok,status:r.status,kind:l,message});},()=>d({ok:false,status:0}),);});})(document);""";
